/* Internal: Unicode character class / simple case mapping tables
 * (generated by tools/gen_unicode.py into unidata.c). */
#ifndef LIBC23_UNIDATA_H
#define LIBC23_UNIDATA_H
#include <stdint.h>

#define UNI_ALPHA 1u
#define UNI_UPPER 2u
#define UNI_LOWER 4u
#define UNI_SPACE 8u
#define UNI_BLANK 16u
#define UNI_CNTRL 32u
#define UNI_GRAPH 64u
#define UNI_PRINT 128u
#define UNI_PUNCT 256u

extern const char __libc_unicode_version[];
unsigned __libc_uni_flags(uint32_t c);
uint32_t __libc_uni_toupper(uint32_t c);
uint32_t __libc_uni_tolower(uint32_t c);
#endif
